import type { Request, Response } from 'express';
import prisma from '../../service/prisma-client';
import { auditLog } from '../../service/app-audit';
import { atClock } from './meal-order.cron';
import { decodeDietList } from './diet-lifecycle';
import { loadPatientContext } from './patient-context';
import { readSettings } from './masters.controller';

/**
 * MealOrder controller — ops surface for the dietary / kitchen staff and
 * ward nurses.
 *
 * One MealOrder row = (admission × meal-time × scheduled-date), generated by
 * `meal-order.cron.ts` from the current plan, diet sheet cells and holds.
 *
 * Lifecycle (DB value → what the hospital calls it):
 *   ORDERED   → "Ordered"   diet communicated to the kitchen
 *   PLATED    → "Prepared"  kitchen has prepared / plated the tray
 *   DELIVERED → "Served"    tray handed to the patient (who served it, 2-ID,
 *                           tray temps for HIC.4; delay reason if after the slot)
 *   CONSUMED  → intake recorded (% + complaint). Drives PSQ.5 KPIs.
 *   SKIPPED   → not served — reason mandatory (NPO, refused, discharged…).
 * Separately: `billed` — DocMinds doesn't bill; staff record that the HIS billed it.
 */

/**
 * Server-local calendar date as YYYY-MM-DD. `toISOString()` gives the UTC
 * date, which is the previous day between 00:00 and 05:30 IST.
 */
function localDateString(d: Date = new Date()): string {
  const pad = (n: number): string => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

/** Short labels for the dietary-practice flags the kitchen must honour. */
function dietFlags(diet?: {
  isVeg: boolean; isJain: boolean; isHalal: boolean; isKosher: boolean; isNoOnionGarlic: boolean;
} | null): string[] {
  if (!diet) return [];
  const flags: string[] = [];
  if (diet.isVeg) flags.push('Veg');
  if (diet.isJain) flags.push('Jain');
  if (diet.isHalal) flags.push('Halal');
  if (diet.isKosher) flags.push('Kosher');
  if (diet.isNoOnionGarlic) flags.push('No onion/garlic');
  return flags;
}

interface PlateBody {
  ids: string[];
}

interface DeliverBody {
  signatureId?: string;
  twoIdVerified?: boolean;
  trayHotTempC?: number;
  trayColdTempC?: number;
  notes?: string;
  /** Person who physically served the tray (ward boy / dietary staff). */
  servedByName?: string;
  /** Mandatory when served after the meal slot's end time. */
  delayReason?: string;
}

interface IntakeBody {
  percentConsumed: number; // 0 | 25 | 50 | 75 | 100
  complaint?: string;
  notes?: string;
}

interface SkipBody {
  reason: string;
}

// ─── Reads ──────────────────────────────────────────────────────────

/**
 * GET /api/dietetics/meal-orders/kitchen?date=YYYY-MM-DD&mealTimeSlotId=...
 *
 * Canteen workspace view — all MealOrders for a given calendar day, optionally
 * narrowed to one meal slot. Each row carries patient + ward + bed + meal so
 * the canteen can print labels / load the trolley.
 */
export const getKitchenList = async (req: Request, res: Response): Promise<void> => {
  try {
    const dateParam = (req.query.date as string) || localDateString();
    const mealTimeSlotId = req.query.mealTimeSlotId as string | undefined;

    const dayStart = new Date(`${dateParam}T00:00:00`);
    const dayEnd = new Date(`${dateParam}T23:59:59.999`);

    const where: Record<string, unknown> = {
      scheduledFor: { gte: dayStart, lte: dayEnd },
    };
    if (mealTimeSlotId) where.mealTimeSlotId = mealTimeSlotId;

    const orders = await prisma.mealOrder.findMany({
      where,
      include: {
        meal: true,
        mealTimeSlot: true,
        dietPlan: { include: { diet: true, texture: true } },
        delivery: true,
        intake: true,
      },
      orderBy: [{ mealTimeSlot: { sequence: 'asc' } }, { wardId: 'asc' }],
    });

    // Hydrate patient + bed from the LIVE admission (IpdAdmission isn't
    // FK-related to MealOrder) — after a transfer the tray shows the new bed.
    const admissionIds = Array.from(new Set(orders.map((o) => o.admissionId)));
    const [patients, alerts] = await Promise.all([
      loadPatientContext({ admissionIds, admittedOnly: false }),
      admissionIds.length
        ? prisma.dietaryAlert.findMany({
            where: { admissionId: { in: admissionIds }, acknowledgedAt: null },
            orderBy: { createdAt: 'desc' },
          })
        : [],
    ]);
    const patientMap = new Map(patients.map((p) => [p.admissionId, p]));
    const alertMap = new Map<string, string[]>();
    for (const a of alerts) alertMap.set(a.admissionId, [...(alertMap.get(a.admissionId) ?? []), a.message]);

    const hydrated = orders.map((o) => {
      const p = patientMap.get(o.admissionId);
      const plan = o.dietPlan;
      return {
        ...o,
        admissionNo: p?.admissionNo ?? null,
        patientName: p?.patientName ?? null,
        prn: p?.prn ?? null,
        wardName: p?.wardName ?? null,
        bedNumber: p?.bedNumber ?? null,
        department: p?.department ?? null,
        displayCode: plan ? (plan.texture ? `${plan.diet.code}-${plan.texture.code}` : plan.diet.code) : null,
        interim: plan?.status === 'INTERIM',
        avoid: [plan?.foodAvoid, ...(plan?.allergensSnapshot ? [`Allergy: ${decodeDietList(plan.allergensSnapshot).join(', ')}`] : [])]
          .filter((s) => s && s !== 'Allergy: ').join(' · ') || null,
        disposablePlate: !!plan?.disposablePlate,
        fluidRestrictionMl: plan?.fluidRestrictionMl ?? null,
        dietFlags: dietFlags(plan?.diet),
        alerts: alertMap.get(o.admissionId) ?? [],
      };
    });

    res.status(200).json(hydrated);
  } catch (error) {
    console.error('[dietetics] getKitchenList failed:', error);
    res.status(500).json({ error: 'Failed to load kitchen list' });
  }
};

/**
 * GET /api/dietetics/meal-orders/admission/:admissionId?date=YYYY-MM-DD
 *
 * Bedside view for the nurse — today's tray schedule for one admission.
 */
export const getForAdmission = async (req: Request, res: Response): Promise<void> => {
  try {
    const admissionId = req.params.admissionId;
    const dateParam = (req.query.date as string) || localDateString();
    const dayStart = new Date(`${dateParam}T00:00:00`);
    const dayEnd = new Date(`${dateParam}T23:59:59.999`);

    const orders = await prisma.mealOrder.findMany({
      where: { admissionId, scheduledFor: { gte: dayStart, lte: dayEnd } },
      include: { meal: true, mealTimeSlot: true, delivery: true, intake: true },
      orderBy: { mealTimeSlot: { sequence: 'asc' } },
    });
    res.status(200).json(orders);
  } catch (error) {
    console.error('[dietetics] getForAdmission failed:', error);
    res.status(500).json({ error: 'Failed to load admission meal orders' });
  }
};

/**
 * GET /api/dietetics/meal-orders/tv/:channelId
 *
 * Canteen TV feed. The meal slot is derived from time-of-day (closest upcoming
 * or active meal slot). The channel's viewSpec picks the wards and the display
 * mode; `?ward=<id>` narrows any channel to one ward (pantry tablet).
 * Output is shaped for the TV component: grouped by ward, with bed + diet name.
 */
export const getTvSnapshot = async (req: Request, res: Response): Promise<void> => {
  try {
    const channelId = req.params.channelId;
    const channel = await prisma.canteenChannel.findUnique({ where: { id: channelId } });
    if (!channel || !channel.isActive) {
      res.status(404).json({ error: 'Channel not found or inactive' });
      return;
    }

    const spec = parseViewSpec(channel.viewSpec);
    const wardParam = typeof req.query.ward === 'string' && req.query.ward.trim() ? req.query.ward.trim() : null;
    // Empty list = every ward (the original behaviour).
    const wardIds = wardParam ? [wardParam] : spec.wardIds;
    const wardNames = wardIds.length
      ? (await prisma.ipdWard.findMany({ where: { id: { in: wardIds } }, select: { wardName: true }, orderBy: { wardName: 'asc' } }))
          .map((w) => w.wardName)
      : [];
    const view = { mode: spec.mode, wardNames };

    // Pick the meal slot whose endTime hasn't passed yet today (or the next
    // upcoming one). Falls back to the first slot.
    const slots = await prisma.mealTimeSlot.findMany({
      where: { isActive: true },
      orderBy: { sequence: 'asc' },
    });
    if (slots.length === 0) {
      res.status(200).json({ channel, view, slot: null, groups: [] });
      return;
    }
    const now = new Date();
    const hhmm = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    // Current meal, else the next one today; after the day's last meal the
    // kitchen is preparing tomorrow's first meal, so show that.
    const current = slots.find((s) => s.startTime <= hhmm && s.endTime >= hhmm)
      ?? slots.find((s) => s.startTime >= hhmm);
    const active = current ?? slots[0];
    // NOW = inside the meal window; NEXT = between meals (kitchen preparing
    // the coming meal); TOMORROW = after the day's last meal.
    const phase = !current ? 'TOMORROW' : current.startTime <= hhmm ? 'NOW' : 'NEXT';
    const serviceDay = new Date(now);
    if (!current) serviceDay.setDate(serviceDay.getDate() + 1);

    const dayStart = new Date(serviceDay); dayStart.setHours(0, 0, 0, 0);
    const dayEnd = new Date(serviceDay); dayEnd.setHours(23, 59, 59, 999);

    const orders = await prisma.mealOrder.findMany({
      where: {
        mealTimeSlotId: active.id,
        scheduledFor: { gte: dayStart, lte: dayEnd },
        status: { in: ['ORDERED', 'PLATED', 'DELIVERED'] },
      },
      include: { meal: true, dietPlan: { include: { diet: true } } },
    });

    const admissionIds = Array.from(new Set(orders.map((o) => o.admissionId)));
    const admissions = admissionIds.length
      ? await prisma.ipdAdmission.findMany({
          // Grouped by the patient's current ward, so filter on that too.
          where: { id: { in: admissionIds }, ...(wardIds.length ? { wardId: { in: wardIds } } : {}) },
          select: {
            id: true, admissionNo: true, prn: true,
            ward: { select: { id: true, wardName: true } },
            bed: { select: { bedNumber: true } },
          },
        })
      : [];
    const admMap = new Map(admissions.map((a) => [a.id, a]));

    // Group by ward for the TV layout. Orders outside the channel's wards have
    // no admission in the map and drop out here.
    const byWard: Record<string, { wardId: string | null; wardName: string; rows: unknown[] }> = {};
    for (const o of orders) {
      const adm = admMap.get(o.admissionId);
      if (!adm) continue;
      const key = adm.ward?.id ?? 'UNASSIGNED';
      const name = adm.ward?.wardName ?? 'Unassigned';
      if (!byWard[key]) byWard[key] = { wardId: adm.ward?.id ?? null, wardName: name, rows: [] };
      byWard[key].rows.push({
        admissionNo: adm.admissionNo,
        bedNumber: adm.bed?.bedNumber ?? null,
        mealName: o.meal?.name ?? '—',
        dietName: o.dietPlan?.diet?.name ?? '—',
        dietFlags: dietFlags(o.dietPlan?.diet),
        status: o.status,
      });
    }

    res.status(200).json({ channel, view, slot: active, phase, serviceDate: localDateString(serviceDay), groups: Object.values(byWard) });
  } catch (error) {
    console.error('[dietetics] getTvSnapshot failed:', error);
    res.status(500).json({ error: 'Failed to load TV snapshot' });
  }
};

// ─── State transitions ──────────────────────────────────────────────

/**
 * POST /api/dietetics/meal-orders/plate
 * body: { ids: string[] }
 *
 * Bulk-plate from the canteen workspace. Idempotent — won't downgrade a row
 * already past PLATED.
 */
export const markPlated = async (req: Request, res: Response): Promise<void> => {
  try {
    const body = req.body as PlateBody;
    if (!Array.isArray(body.ids) || body.ids.length === 0) {
      res.status(400).json({ error: 'ids array is required' });
      return;
    }
    const result = await prisma.mealOrder.updateMany({
      where: { id: { in: body.ids }, status: 'ORDERED' },
      data: {
        status: 'PLATED',
        platedAt: new Date(),
        platedBy: req.user?.username ?? null,
      },
    });
    res.status(200).json({ updated: result.count });
  } catch (error) {
    console.error('[dietetics] markPlated failed:', error);
    res.status(500).json({ error: 'Failed to mark plated' });
  }
};

/**
 * POST /api/dietetics/meal-orders/:id/deliver
 *
 * Creates the MealDelivery row + flips status to DELIVERED. Tray temps and
 * 2-ID verification are captured for HIC.4 evidence.
 */
export const markDelivered = async (req: Request, res: Response): Promise<void> => {
  try {
    const id = req.params.id;
    const body = req.body as DeliverBody;

    const existing = await prisma.mealOrder.findUnique({ where: { id }, include: { mealTimeSlot: true } });
    if (!existing) { res.status(404).json({ error: 'Meal order not found' }); return; }
    // Strict order: ORDERED → PLATED (prepared) → DELIVERED (served). Serving
    // an unprepared tray would skip the kitchen's sign-off on what left it.
    if (existing.status !== 'PLATED') {
      const msg = existing.status === 'ORDERED'
        ? 'Tray must be marked prepared by the kitchen before it is served'
        : `Cannot serve a ${existing.status} order`;
      res.status(409).json({ error: msg });
      return;
    }
    // Served after the slot ended → the hospital wants the reason on record.
    const slotEnd = atClock(existing.scheduledFor, existing.mealTimeSlot.endTime);
    const late = !!slotEnd && new Date() > slotEnd;
    if (late && !body.delayReason?.trim()) {
      res.status(400).json({ error: `Served after ${existing.mealTimeSlot.endTime} — a delay reason is required`, late: true });
      return;
    }

    const result = await prisma.$transaction(async (tx) => {
      await tx.mealDelivery.upsert({
        where: { mealOrderId: id },
        create: {
          mealOrderId: id,
          deliveredBy: req.user?.username ?? null,
          deliveredById: typeof req.user?.id === 'number' ? req.user.id : null,
          signatureId: body.signatureId ?? null,
          twoIdVerified: body.twoIdVerified ?? false,
          trayHotTempC: body.trayHotTempC ?? null,
          trayColdTempC: body.trayColdTempC ?? null,
          notes: body.notes ?? null,
        },
        update: {
          deliveredAt: new Date(),
          deliveredBy: req.user?.username ?? null,
          deliveredById: typeof req.user?.id === 'number' ? req.user.id : null,
          signatureId: body.signatureId ?? null,
          twoIdVerified: body.twoIdVerified ?? false,
          trayHotTempC: body.trayHotTempC ?? null,
          trayColdTempC: body.trayColdTempC ?? null,
          notes: body.notes ?? null,
        },
      });
      return tx.mealOrder.update({
        where: { id },
        data: {
          status: 'DELIVERED',
          deliveredAt: new Date(),
          deliveredBy: req.user?.username ?? null,
          servedByName: body.servedByName?.trim() || req.user?.username || null,
          delayReason: late ? body.delayReason!.trim() : null,
        },
      });
    });

    await auditLog(req, {
      module: 'dietetics',
      action: 'STATUS_CHANGE',
      entityType: 'MealOrder',
      entityId: id,
      payload: {
        from: existing.status, to: 'DELIVERED', twoIdVerified: body.twoIdVerified ?? false,
        servedByName: result.servedByName, late, delayReason: result.delayReason,
      },
    });

    res.status(200).json(result);
  } catch (error) {
    console.error('[dietetics] markDelivered failed:', error);
    res.status(500).json({ error: 'Failed to mark delivered' });
  }
};

/**
 * POST /api/dietetics/meal-orders/:id/intake
 *
 * Records % consumed and flips status to CONSUMED. Auto-sets negativeFlag if
 * < 50% — the dietetics queue picks this up as "needs reassessment".
 */
export const recordIntake = async (req: Request, res: Response): Promise<void> => {
  try {
    const id = req.params.id;
    const body = req.body as IntakeBody;

    if (body.percentConsumed === undefined || body.percentConsumed === null) {
      res.status(400).json({ error: 'percentConsumed is required' });
      return;
    }
    const allowed = [0, 25, 50, 75, 100];
    if (!allowed.includes(body.percentConsumed)) {
      res.status(400).json({ error: `percentConsumed must be one of ${allowed.join(', ')}` });
      return;
    }

    const existing = await prisma.mealOrder.findUnique({ where: { id } });
    if (!existing) { res.status(404).json({ error: 'Meal order not found' }); return; }
    // Intake follows delivery. CONSUMED is allowed so a mis-entered % can be
    // corrected (the MealIntake row is upserted).
    if (existing.status !== 'DELIVERED' && existing.status !== 'CONSUMED') {
      res.status(409).json({ error: `Intake can only be recorded after delivery (order is ${existing.status})` });
      return;
    }

    const negativeFlag = body.percentConsumed < 50;

    const result = await prisma.$transaction(async (tx) => {
      await tx.mealIntake.upsert({
        where: { mealOrderId: id },
        create: {
          mealOrderId: id,
          percentConsumed: body.percentConsumed,
          complaint: body.complaint ?? null,
          notes: body.notes ?? null,
          negativeFlag,
          recordedBy: req.user?.username ?? null,
          recordedById: typeof req.user?.id === 'number' ? req.user.id : null,
        },
        update: {
          percentConsumed: body.percentConsumed,
          complaint: body.complaint ?? null,
          notes: body.notes ?? null,
          negativeFlag,
          recordedAt: new Date(),
          recordedBy: req.user?.username ?? null,
          recordedById: typeof req.user?.id === 'number' ? req.user.id : null,
        },
      });
      return tx.mealOrder.update({
        where: { id },
        data: { status: 'CONSUMED' },
      });
    });

    if (negativeFlag) {
      await auditLog(req, {
        module: 'dietetics',
        action: 'NEGATIVE_INTAKE',
        entityType: 'MealOrder',
        entityId: id,
        payload: { admissionId: existing.admissionId, percent: body.percentConsumed, complaint: body.complaint ?? null },
      });
    }

    res.status(200).json(result);
  } catch (error) {
    console.error('[dietetics] recordIntake failed:', error);
    res.status(500).json({ error: 'Failed to record intake' });
  }
};

/**
 * POST /api/dietetics/meal-orders/:id/skip
 *
 * Patient refused, transferred, NPO order issued, etc. Reason mandatory so
 * the dietician can read it in the queue and react.
 */
export const skipMeal = async (req: Request, res: Response): Promise<void> => {
  try {
    const id = req.params.id;
    const body = req.body as SkipBody;
    if (!body.reason?.trim()) {
      res.status(400).json({ error: 'reason is required' });
      return;
    }

    const existing = await prisma.mealOrder.findUnique({ where: { id } });
    if (!existing) { res.status(404).json({ error: 'Meal order not found' }); return; }
    if (existing.status === 'CONSUMED') {
      res.status(409).json({ error: 'Cannot skip a consumed order' });
      return;
    }

    const updated = await prisma.mealOrder.update({
      where: { id },
      data: { status: 'SKIPPED', skipReason: body.reason.trim() },
    });

    await auditLog(req, {
      module: 'dietetics',
      action: 'STATUS_CHANGE',
      entityType: 'MealOrder',
      entityId: id,
      payload: { from: existing.status, to: 'SKIPPED', reason: body.reason.trim() },
    });

    res.status(200).json(updated);
  } catch (error) {
    console.error('[dietetics] skipMeal failed:', error);
    res.status(500).json({ error: 'Failed to skip meal' });
  }
};

// ─── Canteen TV channel CRUD ────────────────────────────────────────

type TvMode = 'tickets' | 'summary';

/**
 * CanteenChannel.viewSpec is JSON: `{ wardIds?: string[], mode?: 'tickets' | 'summary' }`.
 * Null / unreadable → all wards as tickets, so older channels keep working.
 */
function parseViewSpec(raw: string | null | undefined): { wardIds: string[]; mode: TvMode } {
  try {
    const v = raw ? JSON.parse(raw) : {};
    const wardIds = Array.isArray(v?.wardIds) ? v.wardIds.filter((x: unknown): x is string => typeof x === 'string' && !!x) : [];
    return { wardIds, mode: v?.mode === 'summary' ? 'summary' : 'tickets' };
  } catch {
    return { wardIds: [], mode: 'tickets' };
  }
}

export const listCanteenChannels = async (_req: Request, res: Response): Promise<void> => {
  try {
    const rows = await prisma.canteenChannel.findMany({ orderBy: { createdAt: 'asc' } });
    res.status(200).json(rows);
  } catch (error) {
    console.error('[dietetics] listCanteenChannels failed:', error);
    res.status(500).json({ error: 'Failed to list channels' });
  }
};

export const upsertCanteenChannel = async (req: Request, res: Response): Promise<void> => {
  try {
    const id = req.params.id;
    const { name, isActive, viewSpec } = req.body ?? {};
    if (!name?.trim()) { res.status(400).json({ error: 'name is required' }); return; }
    if (viewSpec != null) {
      try { JSON.parse(viewSpec); } catch { res.status(400).json({ error: 'viewSpec must be valid JSON' }); return; }
    }
    const data = {
      name: name.trim(),
      isActive: isActive ?? true,
      viewSpec: viewSpec ?? null,
    };
    const row = id
      ? await prisma.canteenChannel.update({ where: { id }, data })
      : await prisma.canteenChannel.create({ data });
    res.status(id ? 200 : 201).json(row);
  } catch (error) {
    console.error('[dietetics] upsertCanteenChannel failed:', error);
    res.status(500).json({ error: 'Failed to save channel' });
  }
};

// ─── Manual regenerate (admin tool) ─────────────────────────────────

/**
 * POST /api/dietetics/meal-orders/regenerate?date=YYYY-MM-DD
 *
 * Reconciles MealOrder rows for the given calendar date against the current
 * ACTIVE plans: adds missing rows, re-points / skips rows still ORDERED, and
 * leaves PLATED-or-later rows alone. Slots that are already over are not
 * touched. Idempotent.
 *
 * The actual logic lives in `meal-order.cron.ts` so cron + manual regenerate
 * share the same code path.
 */
export const regenerateForDate = async (req: Request, res: Response): Promise<void> => {
  try {
    const dateParam = (req.query.date as string) || localDateString();
    const target = new Date(`${dateParam}T00:00:00`);
    if (Number.isNaN(target.getTime())) {
      res.status(400).json({ error: 'Invalid date — expected YYYY-MM-DD' });
      return;
    }
    const { generateOrdersForDate } = await import('./meal-order.cron');
    const r = await generateOrdersForDate(target);
    res.status(200).json({
      generated: r.created,
      reassigned: r.reassigned,
      cancelled: r.cancelled,
      date: dateParam,
    });
  } catch (error) {
    console.error('[dietetics] regenerateForDate failed:', error);
    res.status(500).json({
      error: 'Failed to regenerate',
      detail: error instanceof Error ? error.message : String(error),
    });
  }
};

// ─── Billed flag (DocMinds doesn't bill — it records that the HIS did) ─

/** POST /meal-orders/bill  body: { ids: string[], billed: boolean } */
export const markOrdersBilled = async (req: Request, res: Response): Promise<void> => {
  try {
    const { ids, billed = true } = req.body as { ids?: string[]; billed?: boolean };
    if (!Array.isArray(ids) || ids.length === 0) { res.status(400).json({ error: 'ids array is required' }); return; }
    // Only served / consumed trays are billable.
    const result = await prisma.mealOrder.updateMany({
      where: { id: { in: ids }, status: { in: ['DELIVERED', 'CONSUMED'] } },
      data: billed
        ? { billed: true, billedAt: new Date(), billedBy: req.user?.username ?? null }
        : { billed: false, billedAt: null, billedBy: null },
    });
    await auditLog(req, {
      module: 'dietetics', action: 'UPDATE', entityType: 'MealOrderBilling', entityId: null,
      payload: { ids, billed, updated: result.count },
    });
    res.status(200).json({ updated: result.count });
  } catch (error) {
    console.error('[dietetics] markOrdersBilled failed:', error);
    res.status(500).json({ error: 'Failed to update billed flag' });
  }
};

/**
 * GET /billing?from=YYYY-MM-DD&to=YYYY-MM-DD&billed=true|false
 * Served trays + served extra food in the range, for the billing team to tick.
 */
export const getBillingList = async (req: Request, res: Response): Promise<void> => {
  try {
    const from = new Date(`${(req.query.from as string) || localDateString()}T00:00:00`);
    const to = new Date(`${(req.query.to as string) || localDateString()}T23:59:59.999`);
    const billedFilter = req.query.billed === 'true' ? true : req.query.billed === 'false' ? false : undefined;
    const [orders, extras] = await Promise.all([
      prisma.mealOrder.findMany({
        where: {
          scheduledFor: { gte: from, lte: to },
          status: { in: ['DELIVERED', 'CONSUMED'] },
          ...(billedFilter !== undefined && { billed: billedFilter }),
        },
        include: { mealTimeSlot: true, meal: true, dietPlan: { include: { diet: true, texture: true } } },
        orderBy: { scheduledFor: 'asc' },
      }),
      prisma.extraFoodOrder.findMany({
        where: {
          requestedFor: { gte: from, lte: to },
          status: 'SERVED',
          ...(billedFilter !== undefined && { billed: billedFilter }),
        },
        include: { mealTimeSlot: true },
        orderBy: { requestedFor: 'asc' },
      }),
    ]);
    const patients = await loadPatientContext({
      admissionIds: Array.from(new Set([...orders.map((o) => o.admissionId), ...extras.map((e) => e.admissionId)])),
      admittedOnly: false,
    });
    const pMap = new Map(patients.map((p) => [p.admissionId, p]));
    const who = (id: string) => {
      const p = pMap.get(id);
      return { admissionNo: p?.admissionNo ?? null, prn: p?.prn ?? null, patientName: p?.patientName ?? null, bedNumber: p?.bedNumber ?? null, wardName: p?.wardName ?? null };
    };
    res.status(200).json({
      trays: orders.map((o) => ({
        id: o.id, kind: 'TRAY' as const, ...who(o.admissionId),
        date: o.scheduledFor, slot: o.mealTimeSlot.name,
        item: [o.meal?.name, o.kitchenNotes].filter(Boolean).join(' · ') || '—',
        dietCode: o.dietPlan.texture ? `${o.dietPlan.diet.code}-${o.dietPlan.texture.code}` : o.dietPlan.diet.code,
        servedAt: o.deliveredAt, servedBy: o.servedByName ?? o.deliveredBy,
        billed: o.billed, billedAt: o.billedAt, billedBy: o.billedBy,
      })),
      extras: extras.map((e) => ({
        id: e.id, kind: 'EXTRA' as const, ...who(e.admissionId),
        date: e.requestedFor, slot: e.mealTimeSlot?.name ?? null,
        item: `${e.item}${e.quantity ? ` × ${e.quantity}` : ''}${e.forWhom === 'ATTENDANT' ? ' (attendant)' : ''}`,
        dietCode: null,
        servedAt: e.servedAt, servedBy: e.servedByName ?? e.servedBy,
        billed: e.billed, billedAt: e.billedAt, billedBy: e.billedBy,
      })),
    });
  } catch (error) {
    console.error('[dietetics] getBillingList failed:', error);
    res.status(500).json({ error: 'Failed to load billing list' });
  }
};

// ─── Extra food (outside the diet plan: patient extra, attendant, HF patient) ─

const EXTRA_INCLUDE = { mealTimeSlot: { select: { id: true, name: true } } };

export const listExtraFood = async (req: Request, res: Response): Promise<void> => {
  try {
    const dateParam = (req.query.date as string) || localDateString();
    const rows = await prisma.extraFoodOrder.findMany({
      where: {
        requestedFor: { gte: new Date(`${dateParam}T00:00:00`), lte: new Date(`${dateParam}T23:59:59.999`) },
        ...(req.query.admissionId ? { admissionId: req.query.admissionId as string } : {}),
      },
      include: EXTRA_INCLUDE,
      orderBy: { requestedFor: 'asc' },
    });
    const patients = await loadPatientContext({ admissionIds: Array.from(new Set(rows.map((r) => r.admissionId))), admittedOnly: false });
    const pMap = new Map(patients.map((p) => [p.admissionId, p]));
    res.status(200).json(rows.map((r) => {
      const p = pMap.get(r.admissionId);
      return { ...r, admissionNo: p?.admissionNo ?? null, patientName: p?.patientName ?? null, bedNumber: p?.bedNumber ?? null, wardName: p?.wardName ?? null };
    }));
  } catch (error) {
    console.error('[dietetics] listExtraFood failed:', error);
    res.status(500).json({ error: 'Failed to list extra food orders' });
  }
};

export const createExtraFood = async (req: Request, res: Response): Promise<void> => {
  try {
    const { admissionId, forWhom, item, quantity, mealTimeSlotId, requestedFor, notes } = req.body as {
      admissionId: string; forWhom?: string; item: string; quantity?: string; mealTimeSlotId?: string | null;
      requestedFor?: string; notes?: string;
    };
    if (!admissionId || !item?.trim()) { res.status(400).json({ error: 'admissionId and item are required' }); return; }
    const adm = await prisma.ipdAdmission.findFirst({ where: { id: admissionId, status: 'admitted' }, select: { id: true } });
    if (!adm) { res.status(400).json({ error: 'Patient is not currently admitted' }); return; }
    const when = requestedFor ? new Date(requestedFor) : new Date();
    if (Number.isNaN(when.getTime())) { res.status(400).json({ error: 'Invalid requestedFor' }); return; }
    const row = await prisma.extraFoodOrder.create({
      data: {
        admissionId,
        forWhom: forWhom === 'ATTENDANT' ? 'ATTENDANT' : 'PATIENT',
        item: item.trim(),
        quantity: quantity?.trim() || null,
        mealTimeSlotId: mealTimeSlotId || null,
        requestedFor: when,
        notes: notes?.trim() || null,
        requestedBy: req.user?.username ?? null,
      },
      include: EXTRA_INCLUDE,
    });
    await auditLog(req, {
      module: 'dietetics', action: 'CREATE', entityType: 'ExtraFoodOrder', entityId: row.id,
      payload: { admissionId, forWhom: row.forWhom, item: row.item },
    });
    res.status(201).json(row);
  } catch (error) {
    console.error('[dietetics] createExtraFood failed:', error);
    res.status(500).json({ error: 'Failed to create extra food order' });
  }
};

/** POST /extra-food/:id/:action  action = prepare | serve | cancel */
export const updateExtraFood = async (req: Request, res: Response): Promise<void> => {
  try {
    const { id, action } = req.params;
    const body = (req.body ?? {}) as { servedByName?: string; reason?: string };
    const existing = await prisma.extraFoodOrder.findUnique({ where: { id } });
    if (!existing) { res.status(404).json({ error: 'Order not found' }); return; }
    const actor = req.user?.username ?? null;
    let data: Record<string, unknown>;
    if (action === 'prepare') {
      if (existing.status !== 'ORDERED') { res.status(409).json({ error: `Order is ${existing.status}` }); return; }
      data = { status: 'PREPARED', preparedAt: new Date(), preparedBy: actor };
    } else if (action === 'serve') {
      if (existing.status !== 'PREPARED') { res.status(409).json({ error: 'Mark it prepared before serving' }); return; }
      data = { status: 'SERVED', servedAt: new Date(), servedBy: actor, servedByName: body.servedByName?.trim() || actor };
    } else if (action === 'cancel') {
      if (existing.status === 'SERVED') { res.status(409).json({ error: 'Served orders cannot be cancelled' }); return; }
      if (!body.reason?.trim()) { res.status(400).json({ error: 'reason is required' }); return; }
      data = { status: 'CANCELLED', cancelReason: body.reason.trim() };
    } else {
      res.status(400).json({ error: 'action must be prepare, serve or cancel' });
      return;
    }
    const row = await prisma.extraFoodOrder.update({ where: { id }, data, include: EXTRA_INCLUDE });
    await auditLog(req, {
      module: 'dietetics', action: 'STATUS_CHANGE', entityType: 'ExtraFoodOrder', entityId: id,
      payload: { from: existing.status, to: row.status },
    });
    res.status(200).json(row);
  } catch (error) {
    console.error('[dietetics] updateExtraFood failed:', error);
    res.status(500).json({ error: 'Failed to update extra food order' });
  }
};

/** POST /extra-food/bill  body: { ids, billed } */
export const markExtraFoodBilled = async (req: Request, res: Response): Promise<void> => {
  try {
    const { ids, billed = true } = req.body as { ids?: string[]; billed?: boolean };
    if (!Array.isArray(ids) || ids.length === 0) { res.status(400).json({ error: 'ids array is required' }); return; }
    const result = await prisma.extraFoodOrder.updateMany({
      where: { id: { in: ids }, status: 'SERVED' },
      data: billed
        ? { billed: true, billedAt: new Date(), billedBy: req.user?.username ?? null }
        : { billed: false, billedAt: null, billedBy: null },
    });
    await auditLog(req, {
      module: 'dietetics', action: 'UPDATE', entityType: 'ExtraFoodBilling', entityId: null,
      payload: { ids, billed, updated: result.count },
    });
    res.status(200).json({ updated: result.count });
  } catch (error) {
    console.error('[dietetics] markExtraFoodBilled failed:', error);
    res.status(500).json({ error: 'Failed to update billed flag' });
  }
};

// ─── Dietary alerts (admission / discharge / transfer / bed re-occupied) ─

export const listAlerts = async (req: Request, res: Response): Promise<void> => {
  try {
    const includeAcknowledged = req.query.all === 'true';
    const rows = await prisma.dietaryAlert.findMany({
      where: includeAcknowledged
        ? { createdAt: { gte: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000) } }
        : { acknowledgedAt: null },
      orderBy: { createdAt: 'desc' },
      take: 300,
    });
    res.status(200).json(rows);
  } catch (error) {
    console.error('[dietetics] listAlerts failed:', error);
    res.status(500).json({ error: 'Failed to list alerts' });
  }
};

/** POST /alerts/acknowledge  body: { ids: string[] } */
export const acknowledgeAlerts = async (req: Request, res: Response): Promise<void> => {
  try {
    const { ids } = req.body as { ids?: string[] };
    if (!Array.isArray(ids) || ids.length === 0) { res.status(400).json({ error: 'ids array is required' }); return; }
    const result = await prisma.dietaryAlert.updateMany({
      where: { id: { in: ids }, acknowledgedAt: null },
      data: { acknowledgedAt: new Date(), acknowledgedBy: req.user?.username ?? null },
    });
    res.status(200).json({ updated: result.count });
  } catch (error) {
    console.error('[dietetics] acknowledgeAlerts failed:', error);
    res.status(500).json({ error: 'Failed to acknowledge alerts' });
  }
};

// ─── Diet labels (per meal) ─────────────────────────────────────────

/**
 * GET /labels?date=YYYY-MM-DD&mealTimeSlotId=&wardId=
 * One label per tray (not skipped) + per extra-food order for that meal,
 * with the label layout from settings. The page renders + prints them.
 */
export const getLabels = async (req: Request, res: Response): Promise<void> => {
  try {
    const dateParam = (req.query.date as string) || localDateString();
    const mealTimeSlotId = req.query.mealTimeSlotId as string | undefined;
    const wardId = req.query.wardId as string | undefined;
    if (!mealTimeSlotId) { res.status(400).json({ error: 'mealTimeSlotId is required' }); return; }
    const dayStart = new Date(`${dateParam}T00:00:00`);
    const dayEnd = new Date(`${dateParam}T23:59:59.999`);

    const [orders, extras, slot, settings] = await Promise.all([
      prisma.mealOrder.findMany({
        where: {
          mealTimeSlotId, scheduledFor: { gte: dayStart, lte: dayEnd },
          status: { not: 'SKIPPED' },
          ...(wardId && { wardId }),
        },
        include: { meal: true, dietPlan: { include: { diet: true, texture: true } } },
      }),
      prisma.extraFoodOrder.findMany({
        where: { mealTimeSlotId, requestedFor: { gte: dayStart, lte: dayEnd }, status: { not: 'CANCELLED' } },
      }),
      prisma.mealTimeSlot.findUnique({ where: { id: mealTimeSlotId } }),
      readSettings(),
    ]);
    const patients = await loadPatientContext({
      admissionIds: Array.from(new Set([...orders.map((o) => o.admissionId), ...extras.map((e) => e.admissionId)])),
    });
    const pMap = new Map(patients.map((p) => [p.admissionId, p]));

    const labels = [
      ...orders.map((o) => {
        const p = pMap.get(o.admissionId);
        const plan = o.dietPlan;
        const allergens = decodeDietList(plan.allergensSnapshot);
        return {
          id: o.id,
          kind: 'TRAY' as const,
          bedNumber: p?.bedNumber ?? null,
          wardName: p?.wardName ?? null,
          patientName: p?.patientName ?? null,
          prn: p?.prn ?? null,
          admissionNo: p?.admissionNo ?? null,
          dietCode: plan.texture ? `${plan.diet.code}-${plan.texture.code}` : plan.diet.code,
          item: [o.meal?.name, o.kitchenNotes].filter(Boolean).join(' · ') || null,
          avoid: [plan.foodAvoid, allergens.length ? `Allergy: ${allergens.join(', ')}` : null].filter(Boolean).join(' · ') || null,
          disposable: plan.disposablePlate,
          fluidRestrictionMl: plan.fluidRestrictionMl,
          flags: dietFlags(plan.diet),
          qr: `MO:${o.id}`,
        };
      }),
      ...extras.map((e) => {
        const p = pMap.get(e.admissionId);
        return {
          id: e.id,
          kind: 'EXTRA' as const,
          bedNumber: p?.bedNumber ?? null,
          wardName: p?.wardName ?? null,
          patientName: e.forWhom === 'ATTENDANT' ? `Attendant of ${p?.patientName ?? ''}`.trim() : (p?.patientName ?? null),
          prn: p?.prn ?? null,
          admissionNo: p?.admissionNo ?? null,
          dietCode: 'EXTRA',
          item: `${e.item}${e.quantity ? ` × ${e.quantity}` : ''}`,
          avoid: null,
          disposable: false,
          fluidRestrictionMl: null,
          flags: [] as string[],
          qr: `XF:${e.id}`,
        };
      }),
    ].sort((a, b) => (a.wardName ?? '').localeCompare(b.wardName ?? '')
        || (a.bedNumber ?? '').localeCompare(b.bedNumber ?? '', undefined, { numeric: true }));

    res.status(200).json({
      date: dateParam,
      slot: slot ? { id: slot.id, name: slot.name, startTime: slot.startTime } : null,
      layout: {
        widthMm: settings.labelWidthMm, heightMm: settings.labelHeightMm,
        columns: settings.labelColumns, showQr: settings.labelShowQr,
      },
      labels,
    });
  } catch (error) {
    console.error('[dietetics] getLabels failed:', error);
    res.status(500).json({ error: 'Failed to build labels' });
  }
};
